/// Which scalar php names in `Trying to access array offset on <word>`.
#[derive(Clone, Copy)]
pub(super) enum ScalarOffsetBase {
    /// The word is known while lowering: `false`, `int`, `float`.
    Known(&'static str),
    /// A `bool` whose VALUE decides the word. php names what the variable actually holds, so
    /// `true` and `false` are told apart at run time — a literal `true` types as plain `bool`
    /// here, so this is the ordinary spelling, not an exotic one.
    BoolAtRuntime,
}

/// Returns the scalar php would name for an offset read through `value`, if any.
///
/// A STRING base is not one: `"abc"[1]` is a legal read. Nor is `Mixed`, which carries its type
/// at run time and is dispatched by the runtime helpers.
pub(super) fn scalar_offset_base(
    ctx: &LoweringContext<'_, '_>,
    value: crate::ir::ValueId,
) -> Option<ScalarOffsetBase> {
    match ctx.builder.value_php_type(value) {
        PhpType::False => Some(ScalarOffsetBase::Known("false")),
        PhpType::Int => Some(ScalarOffsetBase::Known("int")),
        PhpType::Float => Some(ScalarOffsetBase::Known("float")),
        PhpType::Bool => Some(ScalarOffsetBase::BoolAtRuntime),
        _ => None,
    }
}

